import { i18n } from '@osd/i18n';
import { useMemo, useCallback, useState } from 'react';
import { fetchAnchor } from '../api/anchor';
import { fetchSurroundingDocs } from '../api/context';
import { useOpenSearchDashboards } from '../../../../../../../opensearch_dashboards_react/public';
import { CONTEXT_TIE_BREAKER_FIELDS_SETTING } from '../../../../../../common';
import { getFirstSortableField, SortDirection } from '../api/utils/sorting';
import { SurrDocType } from '../api/context';
import { FAILURE_REASONS, LOADING_STATUS } from './context_query_state';
const initialState = {
  anchor: {},
  predecessors: [],
  successors: [],
  anchorStatus: {
    value: LOADING_STATUS.UNINITIALIZED
  },
  predecessorsStatus: {
    value: LOADING_STATUS.UNINITIALIZED
  },
  successorsStatus: {
    value: LOADING_STATUS.UNINITIALIZED
  }
};
export function useQueryActions(anchorId, indexPattern) {
  const {
    services
  } = useOpenSearchDashboards();
  const {
    data,
    uiSettings,
    toastNotifications
  } = services;
  const searchSource = useMemo(() => {
    return data.search.searchSource.createEmpty();
  }, [data.search.searchSource]);
  const tieBreakerField = useMemo(() => getFirstSortableField(indexPattern, uiSettings.get(CONTEXT_TIE_BREAKER_FIELDS_SETTING)), [uiSettings, indexPattern]);
  const [contextQueryState, setContextQueryState] = useState(initialState);
  const fetchAnchorRow = useCallback(async () => {
    if (!tieBreakerField) {
      setContextQueryState(prevState => ({
        ...prevState,
        anchorStatus: {
          value: LOADING_STATUS.FAILED,
          reason: FAILURE_REASONS.INVALID_TIEBREAKER
        }
      }));
      return;
    }
    try {
      setContextQueryState(prevState => ({
        ...prevState,
        anchorStatus: {
          value: LOADING_STATUS.LOADING
        }
      }));
      const sort = [{
        [indexPattern.timeFieldName]: SortDirection.desc
      }, {
        [tieBreakerField]: SortDirection.desc
      }];
      const fetchAnchorResult = await fetchAnchor(anchorId, indexPattern, searchSource, sort);
      setContextQueryState(prevState => ({
        ...prevState,
        anchor: fetchAnchorResult,
        anchorStatus: {
          value: LOADING_STATUS.LOADED
        }
      }));
      return fetchAnchorResult;
    } catch (error) {
      setContextQueryState(prevState => ({
        ...prevState,
        anchorStatus: {
          value: LOADING_STATUS.FAILED,
          reason: FAILURE_REASONS.UNKNOWN
        }
      }));
      toastNotifications.addDanger({
        title: i18n.translate('discover.context.unableToLoadAnchorDocumentDescription', {
          defaultMessage: '기준 문서를 불러올 수 없습니다'
        }),
        text: 'fail'
      });
    }
  }, [anchorId, indexPattern, searchSource, tieBreakerField, toastNotifications]);
  const fetchSurroundingRows = useCallback(async (type, count, filters, anchor) => {
    try {
      if (type === SurrDocType.PREDECESSORS) {
        setContextQueryState(prevState => ({
          ...prevState,
          predecessorsStatus: {
            value: LOADING_STATUS.LOADING
          }
        }));
      } else {
        setContextQueryState(prevState => ({
          ...prevState,
          successorsStatus: {
            value: LOADING_STATUS.LOADING
          }
        }));
      }
      const fetchedAchor = anchor || contextQueryState.anchor;
      const rows = await fetchSurroundingDocs(type, indexPattern, fetchedAchor, tieBreakerField, SortDirection.desc, count, filters);
      if (type === SurrDocType.PREDECESSORS) {
        setContextQueryState(prevState => ({
          ...prevState,
          predecessors: rows,
          predecessorsStatus: {
            value: LOADING_STATUS.LOADED
          }
        }));
      } else {
        setContextQueryState(prevState => ({
          ...prevState,
          successors: rows,
          successorsStatus: {
            value: LOADING_STATUS.LOADED
          }
        }));
      }
    } catch (error) {
      if (type === SurrDocType.PREDECESSORS) {
        setContextQueryState(prevState => ({
          ...prevState,
          predecessorsStatus: {
            value: LOADING_STATUS.FAILED,
            reason: FAILURE_REASONS.UNKNOWN
          }
        }));
      } else {
        setContextQueryState(prevState => ({
          ...prevState,
          successorsStatus: {
            value: LOADING_STATUS.FAILED,
            reason: FAILURE_REASONS.UNKNOWN
          }
        }));
      }
      toastNotifications.addDanger({
        title: i18n.translate('discover.context.unableToLoadSurroundingDocumentDescription', {
          defaultMessage: '주변 문서를 불러올 수 없습니다'
        }),
        text: 'fail'
      });
    }
  }, [contextQueryState.anchor, indexPattern, tieBreakerField, toastNotifications]);
  const fetchContextRows = useCallback(async (predecessorCount, successorCount, filters, anchor) => Promise.all([fetchSurroundingRows(SurrDocType.PREDECESSORS, predecessorCount, filters, anchor), fetchSurroundingRows(SurrDocType.SUCCESSORS, successorCount, filters, anchor)]), [fetchSurroundingRows]);
  const fetchAllRows = useCallback(async (predecessorCount, successorCount, filters) => {
    try {
      await fetchAnchorRow().then(anchor => anchor && fetchContextRows(predecessorCount, successorCount, filters, anchor));
    } catch (error) {
      toastNotifications.addDanger({
        title: i18n.translate('discover.context.unableToLoadDocumentDescription', {
          defaultMessage: '전체 문서를 불러올 수 없습니다'
        }),
        text: 'fail'
      });
    }
  }, [fetchAnchorRow, fetchContextRows, toastNotifications]);
  const resetContextQueryState = useCallback(() => {
    setContextQueryState(initialState);
  }, []);
  return {
    contextQueryState,
    fetchAnchorRow,
    fetchAllRows,
    fetchContextRows,
    fetchSurroundingRows,
    resetContextQueryState
  };
}